describe('Username Pre-fill on Login', () => {
    beforeEach(() => {
        cy.visit('/login');
        // Simulate a previous login by setting a cookie or local storage
        cy.setCookie('session_id', '123456'); // Example of setting a session cookie
        cy.setLocalStorage('username', 'testUser'); // Example of setting a username in local storage
    });

    it('should pre-fill the username field with the previously logged in username', () => {
        cy.get('input[name="username"]').should('have.value', 'testUser');
    });

    it('should not pre-fill the username field if no previous login exists', () => {
        // Clear the local storage to simulate no previous login
        cy.clearLocalStorage();
        cy.visit('/login');
        cy.get('input[name="username"]').should('have.value', '');
    });
});
